<h1>Balance Adjustments</h1>
<div class="card"><form method="post" class="grid"><?=csrf_field()?><p><label>Account</label><select name="account_id" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?> (<?=e($a['currency'])?>)</option><?php endforeach;?></select></p><p><label>Amount (+/-)</label><input type="number" name="amount" step="0.01" required></p><p><label>Date/time</label><input type="datetime-local" name="adjusted_at" value="<?=date('Y-m-d\TH:i')?>" required></p><p><label>Reason</label><input name="reason" maxlength="255" required></p><p style="align-self:end"><button>Record adjustment</button></p></form></div>
<div class="card"><h2>History</h2><div class="table-wrap"><table><tr><th>Date</th><th>Account</th><th>Amount</th><th>Reason</th></tr><?php foreach($adjustments as $a):?><tr><td><?=e($a['adjusted_at'])?></td><td><?=e($a['account_name'])?></td><td class="<?=((float)$a['amount']>=0?'positive':'negative')?>"><?=number_format((float)$a['amount'],2)?> <?=e($a['currency'])?></td><td><?=e($a['reason'])?></td></tr><?php endforeach;?><?php if(!$adjustments):?><tr><td colspan="4" class="muted">No balance adjustments.</td></tr><?php endif;?></table></div></div>
